INSERT INTO system.company_setting (id, singleton, company_name_en, company_name_ar, cr_number, vat_id, vat_enabled, vat_percentage, vat_certificate_url, default_currency, currency_decimals, address_en, address_ar, phone, country_code, mobile_number, whatsapp_phone, whatsapp_country_code, whatsapp_mobile_number, email, website, instagram_url, linkedin_url, youtube_url, map_url, bank_name, bank_iban, bank_account_number, bank_swift, time_zone, logo_url, dark_logo_url, full_logo_url, dark_full_logo_url, icon_url, dark_icon_url, stamp_url, signature_url, document_header_url, document_footer_url, payment_terms_days, invoice_prefix, invoice_next_number, receipt_prefix, receipt_next_number, ceo_name_en, ceo_name_ar, ceo_title_en, ceo_title_ar, ceo_quote_en, ceo_quote_ar, tagline_en, tagline_ar, about_text_en, about_text_ar, mission_en, mission_ar, vision_en, vision_ar, terms_en, terms_ar, rules_en, rules_ar, founded_year, city, country, primary_language, business_activity, default_discount_limit_percent, quotations_always_need_approval, theme, setup_completed_at, website_domain, admin_domain, updated_at) VALUES ('c0000000-0000-0000-0000-000000000001', 1, 'ishoot Cinema Production S.P.C.', 'دار آي شوت للإنتاج السينمائي ذ.م.م', 'CR-142859-1', '200019283700002', true, 10, '/api/files/brand/stamp.png', 'BHD', 3, 'Office 402, Platinum Tower, Seef District, Manama, Kingdom of Bahrain', 'مكتب 402، برج بلاتينيوم، ضاحية السيف، المنامة، مملكة البحرين', '+97317000000', 'BH', '17000000', '+97339000000', 'BH', '39000000', 'hello@ishoot.bh', 'https://ishoot.bh', 'https://instagram.com/ishoot', 'https://linkedin.com/company/ishoot', 'https://youtube.com/@ishoot', 'https://maps.google.com/?q=Manama%2C%20Bahrain', 'National Bank of Bahrain (NBB)', 'BH29NBOB00000012345678', '0012345678', 'NBOBBHBM', 'Asia/Bahrain', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/icon-light.png', '/api/files/brand/icon-dark.png', '/api/files/brand/stamp.png', '/api/files/brand/signature.png', '/api/files/media/banners/banner-01.png', '/api/files/media/banners/banner-02.png', 30, 'ISH', 150, 'RCT', 150, 'Ali Al-Arrayed', 'علي العريض', 'Managing Director & Executive Producer', 'المدير العام والمنتج التنفيذي', 'Precision delivery from Manama across the GCC.', 'التميز التشغيلي من Manama إلى جميع أسواق الخليج.', 'Cinema Production & Creative Media Studio', 'استوديو الإنتاج السينمائي والإعلام الإبداعي', 'Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.', 'دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي.', 'Deliver benchmark media services with clear bilingual accountability.', 'تقديم خدمات موثوقة ثنائية اللغة وفق أعلى معايير الجودة والالتزام.', 'To lead Bahrain''s enterprise ecosystem in media innovation.', 'أن نكون الشريك المرجعي الأول لقطاع الأعمال في مملكة البحرين والخليج.', 'Invoices are payable within 30 calendar days in BHD. Late balances accrue documented reminders.', 'تستحق الفواتير خلال 30 يوماً بعملة BHD وفق شروط العقد المعتمد.', '10% VAT compliant with Bahrain NBR e-invoicing guidelines; signed approvals logged digitally.', 'تطبق ضريبة القيمة المضافة 10% وفق متطلبات الجهاز الوطني للإيرادات.', 2018, 'Manama', 'BH', 'ar', 'media', 15, false, NULL, '2026-01-01T00:00:00Z', 'ishoot.bh', 'admin.ishoot.bh', now()) ON CONFLICT (id) DO NOTHING;
