INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'ishoot-case-1', 'Bahrain Bay Waterfront Architecture Film', 'فيلم معماري لواجهة خليج البحرين', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Manama with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Manama وفق أعلى معايير الجودة والالتزام.', 7000, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://ishoot.bh/work/ishoot-case-1', 'Manama, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'ishoot-2026-outlook', 'ishoot 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — آي شوت', 'Key operational benchmarks, real metrics, and 2026 guidance from ishoot in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من آي شوت في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography. Focusing on Cinema Commercial Production, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي. من خلال خدمة إنتاج الأفلام الإعلانية السينمائية نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.</p><p>Focusing on <strong>Cinema Commercial Production</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي.</p><p>من خلال خدمة <strong>إنتاج الأفلام الإعلانية السينمائية</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'ishoot 2026 GCC Market Outlook & Benchmarks | ishoot', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — آي شوت | آي شوت', 'Executive guide by ishoot covering Cinema Commercial Production benchmarks in Bahrain.', 'دليل تنفيذي من آي شوت حول معايير إنتاج الأفلام الإعلانية السينمائية في البحرين.', 'Insights', '{"media","insights","Manama","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can ishoot initiate a Cinema Commercial Production engagement?', 'كم يستغرق بدء تنفيذ خدمة إنتاج الأفلام الإعلانية السينمائية لدى آي شوت؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Manama.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Manama.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'ishoot-case-2', 'National Industrial Summit Keynote & Recap', 'التغطية الرئيسية لقمة الصناعة الوطنية', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Manama with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Manama وفق أعلى معايير الجودة والالتزام.', 14400, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://ishoot.bh/work/ishoot-case-2', 'Manama, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'ishoot-service-standards', 'Inside Our Production SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في إنتاج الأفلام الإعلانية السينمائية', 'Key operational benchmarks, real metrics, and 2026 guidance from ishoot in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من آي شوت في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography. Focusing on Brand Documentary Film, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي. من خلال خدمة فيلم وثائقي للعلامة التجارية نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.</p><p>Focusing on <strong>Brand Documentary Film</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي.</p><p>من خلال خدمة <strong>فيلم وثائقي للعلامة التجارية</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Production SLA: Speed, Quality & Auditability | ishoot', 'معايير اتفاقية مستوى الخدمة والجودة في إنتاج الأفلام الإعلانية السينمائية | آي شوت', 'Executive guide by ishoot covering Brand Documentary Film benchmarks in Bahrain.', 'دليل تنفيذي من آي شوت حول معايير فيلم وثائقي للعلامة التجارية في البحرين.', 'Operations', '{"media","operations","Manama","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-142859-1 and VAT ID 200019283700002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-142859-1 والرقم الضريبي 200019283700002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
