INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-3', 'ishoot-arabic-bilingual-ops', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from ishoot in Manama.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من آي شوت في Manama.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography. Focusing on ARRI / RED Cinema Package Rental, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي. من خلال خدمة تأجير حزمة كاميرات آري وريد نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Premier cinematic media production house in the Kingdom of Bahrain, crafting narrative-driven brand films, commercials, and aerial cinematography.</p><p>Focusing on <strong>ARRI / RED Cinema Package Rental</strong>, our Manama specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>دار إنتاج سينمائي رائدة في مملكة البحرين، متخصصة في صناعة الأفلام الإعلانية الوثائقية والتصوير الجوي السينمائي.</p><p>من خلال خدمة <strong>تأجير حزمة كاميرات آري وريد</strong>، يعمل فريقنا في Manama على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises | ishoot', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين | آي شوت', 'E