INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-3', 'Which corporate payment channels do you support?', 'ما هي قنوات الدفع المؤسسية المتاحة لديكم؟', 'We accept National Bank of Bahrain (NBB) corporate wire/IBAN, BenefitPay, corporate cards, and approved 30-day credit terms.', 'نقبل التحويل البنكي المباشر لحساب National Bank of Bahrain (NBB) وبنفت باي والبطاقات وفترات الائتمان 30 يوماً.', 'payments', true, 3, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
